      "policy_source_id": "q12",
      "interpretation": "Before executing `cancel_appointment`, the assistant must obtain explicit confirmation from the patient in Russian ('да').",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "q12",
      "actor": "system",
      "role": "policy_span",
      "fact": "Before `cancel_appointment`, state the details and obtain explicit confirmation ('да') from the patient."
    },
